                String fqn = ( (TypeElement) annotationElement ).getQualifiedName().toString();
                if ( JSpecifyConstants.NULL_MARKED_FQN.equals( fqn ) ) {
                    return true;
                }
                if ( JSpecifyConstants.NULL_UNMARKED_FQN.equals( fqn ) ) {
                    return false;
                }
            }
            current = current.getEnclosingElement();
        }
        return false;
    }

