import static org.mapstruct.ap.internal.util.Collections.first;

/**
 * A {@link MappingMethod} implemented by a {@link Mapper} class which maps one iterable type to another. The collection
 * elements are mapped either by a {@link TypeConversion} or another mapping method.
 *
 * @author Gunnar Morling
 */
public class IterableMappingMethod extends ContainerMappingMethod {

    public static class Builder extends ContainerMappingMethodBuilder<Builder, IterableMappingMethod> {

        private Type sourceElementType;
        private Type targetElementType;

        public Builder() {
            super( Builder.class, "collection element" );
        }

        @Override
        protected Type getElementType(Type parameterType) {
            if ( parameterType.isMapType() ) {
                return ctx.getTypeFactory().getMapEntryType( parameterType, false );
            }
            return parameterType.isArrayType() ? parameterType.getComponentType() : first(
                parameterType.determineTypeArguments( Iterable.class ) ).getTypeBound();
        }

        @Override
        protected Type getSourceElementType(Type sourceType) {
            sourceElementType = getElementType( sourceType );
            return sourceElementType;
        }

        @Override
        protected Type getTargetElementType(Type targetType) {
            targetElementType = targetType.isMapType()
                ? ctx.getTypeFactory().getMapEntryType( targetType, true )
                : getElementType( targetType );
            return targetElementType;
        }

        @Override
        protected Assignment getWrapper(Assignment assignment, Method method) {
            Type resultType = method.getResultType();
            // target accessor is setter, so decorate assignment as setter
            if ( resultType.isArrayType() || resultType.isMapType() ) {
                return new LocalVarWrapper( assignment, method.getThrownTypes(), targetElementType, false );
            }
            else {
                return new SetterWrapper( assignment, method.getThrownTypes(), false );
            }
        }

        @Override
        protected IterableMappingMethod instantiateMappingMethod(Method method, Collection<String> existingVariables,
            Assignment assignment, MethodReference factoryMethod, boolean mapNullToDefault, String loopVariableName,
            List<LifecycleCallbackMethodReference> beforeMappingMethods,
            List<LifecycleCallbackMethodReference> afterMappingMethods, SelectionParameters selectionParameters,
            PresenceCheck sourceParameterPresenceCheck) {
            return new IterableMappingMethod(
                method,
                getMethodAnnotations(),
                existingVariables,
                assignment,
                factoryMethod,
                mapNullToDefault,
                loopVariableName,
                beforeMappingMethods,
                afterMappingMethods,
                selectionParameters,
                sourceParameterPresenceCheck,
                sourceElementType,
                targetElementType
            );
        }
    }

    private final Type sourceElementType;
    private final Type resultElementType;

    //CHECKSTYLE:OFF
    private IterableMappingMethod(Method method, List<Annotation> annotations,
                                  Collection<String> existingVariables, Assignment parameterAssignment,
                                  MethodReference factoryMethod, boolean mapNullToDefault, String loopVariableName,
                                  List<LifecycleCallbackMethodReference> beforeMappingReferences,
                                  List<LifecycleCallbackMethodReference> afterMappingReferences,
        SelectionParameters selectionParameters, PresenceCheck sourceParameterPresenceCheck,
        Type sourceElementType, Type resultElementType) {
        //CHECKSTYLE:ON
        super(
            method,
            annotations,
            existingVariables,
            parameterAssignment,
            factoryMethod,
            mapNullToDefault,
            loopVariableName,
            beforeMappingReferences,
            afterMappingReferences,
            selectionParameters,
            sourceParameterPresenceCheck
        );
        this.sourceElementType = sourceElementType;
        this.resultElementType = resultElementType;
    }

    @Override
    public Set<Type> getImportTypes() {
        Set<Type> types = super.getImportTypes();

        types.add( getSourceElementType() );
        return types;
    }

    public Type getSourceElementType() {
        return sourceElementType;
    }

    @Override
    public Type getResultElementType() {
        return resultElementType;
    }

}

